// eslint-disable-next-line no-restricted-imports
import {toPercentInt} from '@github-ui/secret-scanning/utils'
import type {PatternOverride} from '../types'

export const SortProperty = {
  Name: 'name',
  AlertTotal: 'alert-total',
  FalsePositiveRate: 'false-positive-rate',
  BypassRate: 'bypass-rate',
} as const

export type SortProperty = (typeof SortProperty)[keyof typeof SortProperty]

export const SortDirection = {
  Ascending: 'ASC',
  Descending: 'DESC',
} as const

export type SortDirection = (typeof SortDirection)[keyof typeof SortDirection]

export function SortPatternOverrides(
  patternOverrides: PatternOverride[],
  column: SortProperty,
  direction: SortDirection,
): PatternOverride[] {
  const out = [...patternOverrides]
  out.sort((a, b) => {
    return sortByColumn(a, b, column) * (direction === SortDirection.Ascending ? 1 : -1)
  })
  return out
}

function sortByColumn(a: PatternOverride, b: PatternOverride, column: SortProperty): number {
  switch (column) {
    case SortProperty.Name:
      return a.display_name.localeCompare(b.display_name)
    case SortProperty.AlertTotal:
      return a.alert_total - b.alert_total
    case SortProperty.FalsePositiveRate: {
      return toPercentInt(a.false_positives, a.alert_total) - toPercentInt(b.false_positives, b.alert_total)
    }
    case SortProperty.BypassRate: {
      return toPercentInt(a.bypasses, a.blocks) - toPercentInt(b.bypasses, b.blocks)
    }
    default:
      column satisfies never
      return 0
  }
}
