import safeStorage from '@github-ui/safe-storage'

export const VERSION_MISMATCH_RATE_LIMIT_DURATION = 1000 * 60 * 60 * 24 // 24 hours in milliseconds

const STORAGE_KEY = 'VERSION_MISMATCH_LAST_TRIGGERED'
const STORAGE_TTL = VERSION_MISMATCH_RATE_LIMIT_DURATION + 1000 * 60 * 60 // 1 hour race/edge condition buffer

const rateLimitStorage = safeStorage('localStorage', {
  ttl: STORAGE_TTL,
  throwQuotaErrorsOnSet: false,
})

let inMemoryFallback: number | null = null

/**
 * Global rate limiter for version mismatch detection.
 * Ensures version mismatch callbacks are only triggered once per 24 hours
 * across all apps regardless of client version.
 */
export class VersionMismatchRateLimiter {
  /**
   * Checks if a version mismatch trigger is allowed.
   * Returns true if it's been more than 24 hours since the last trigger,
   * or if this is the first trigger.
   *
   * @returns true if trigger is allowed, false if rate limited
   */
  canTrigger(): boolean {
    const lastTriggerTime = this.getLastTriggerTime()

    if (lastTriggerTime === null) {
      return true // Never triggered before
    }

    const timeSinceLastTrigger = Date.now() - lastTriggerTime
    return timeSinceLastTrigger >= VERSION_MISMATCH_RATE_LIMIT_DURATION
  }

  /**
   * Records that a version mismatch trigger occurred.
   * Stores the timestamp in localStorage with fallback to in-memory storage.
   */
  recordTrigger(): void {
    const timestamp = Date.now()
    rateLimitStorage.setItem(STORAGE_KEY, timestamp.toString())
    inMemoryFallback = timestamp
  }

  /**
   * Gets the timestamp of the last version mismatch trigger.
   * Checks localStorage first, then falls back to in-memory storage.
   *
   * @returns Timestamp of last trigger, or null if never triggered
   */
  getLastTriggerTime(): number | null {
    const storedValue = rateLimitStorage.getItem(STORAGE_KEY)
    if (storedValue) {
      const timestamp = parseInt(storedValue, 10)
      return isNaN(timestamp) ? null : timestamp
    }

    return inMemoryFallback
  }

  /**
   * Clears the rate limiting data.
   * Useful for testing or manual reset scenarios.
   */
  clearTriggerRecord(): void {
    rateLimitStorage.removeItem(STORAGE_KEY)
    inMemoryFallback = null
  }
}

export const versionMismatchRateLimiter = new VersionMismatchRateLimiter()
